package ec.edu.ucacue.odontocare.treatment.domain;
import ec.edu.ucacue.odontocare.odontogram.domain.DentalPiece;import jakarta.persistence.*;
@Entity @Table(name="treatment_plan_items") public class TreatmentPlanItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="treatment_plan_id")private TreatmentPlan plan;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="dental_piece_id")private DentalPiece piece;private String description;private Short priority;@Column(name="sessions_estimated")private Short sessionsEstimated;@Enumerated(EnumType.STRING)private TreatmentItemStatus status;private String observations;@Column(name="created_by")private Long createdBy;protected TreatmentPlanItem(){}public TreatmentPlanItem(TreatmentPlan p,DentalPiece piece,String description,short priority,short sessions,String observations,Long user){plan=p;this.piece=piece;this.description=description;this.priority=priority;this.sessionsEstimated=sessions;this.observations=observations;status=TreatmentItemStatus.PENDING;createdBy=user;}public void changeStatus(TreatmentItemStatus value){status=value;}public Long getId(){return id;}public DentalPiece getPiece(){return piece;}public String getDescription(){return description;}public Short getPriority(){return priority;}public Short getSessionsEstimated(){return sessionsEstimated;}public TreatmentItemStatus getStatus(){return status;}public String getObservations(){return observations;}}
